e2e_surface.body:
{
    let cert = surface_certificate()?;
    if cert.partition_four != 5 {
        return Err(SurfaceError {
            invariant: "crate root repeats the partition witness p(4)=5",
            parameters: format!("partition_four={}", cert.partition_four),
        });
    }
    Ok(cert)
}
